CREATE TABLE public.transactions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),lot_id uuid NOT NULL REFERENCES public.lots(id),buyer_id uuid NOT NULL,seller_id uuid,final_price numeric NOT NULL,buyer_commission numeric NOT NULL DEFAULT 0,seller_commission numeric NOT NULL DEFAULT 0,status text DEFAULT 'pending',payment_status text DEFAULT 'unpaid',payment_gateway_id uuid,gateway_reference text,payment_method text,checkout_url text,gateway_status text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(lot_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.transactions TO authenticated;GRANT ALL ON public.transactions TO service_role;ALTER TABLE public.transactions ENABLE ROW LEVEL SECURITY;CREATE POLICY transactions_read ON public.transactions FOR SELECT TO authenticated USING(buyer_id=auth.uid() OR seller_id=auth.uid() OR public.is_admin());CREATE POLICY transactions_create ON public.transactions FOR INSERT TO authenticated WITH CHECK(buyer_id=auth.uid() OR public.is_admin());CREATE POLICY transactions_admin_update ON public.transactions FOR UPDATE TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());CREATE POLICY transactions_admin_delete ON public.transactions FOR DELETE TO authenticated USING(public.is_admin());
CREATE TABLE public.contracts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),transaction_id uuid NOT NULL REFERENCES public.transactions(id) ON DELETE CASCADE,contract_url text,status text DEFAULT 'draft',signed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.contracts TO authenticated;GRANT ALL ON public.contracts TO service_role;ALTER TABLE public.contracts ENABLE ROW LEVEL SECURITY;CREATE POLICY contracts_read ON public.contracts FOR SELECT TO authenticated USING(public.is_admin() OR EXISTS(SELECT 1 FROM public.transactions t WHERE t.id=transaction_id AND (t.buyer_id=auth.uid() OR t.seller_id=auth.uid())));CREATE POLICY contracts_admin ON public.contracts FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE TABLE public.installments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),transaction_id uuid NOT NULL REFERENCES public.transactions(id) ON DELETE CASCADE,buyer_id uuid NOT NULL,amount numeric NOT NULL,due_date timestamptz NOT NULL,installment_number integer NOT NULL,status text DEFAULT 'pending',payment_method text DEFAULT 'pix_manual',proof_url text,paid_at timestamptz,external_reference text,gateway_status text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(transaction_id,installment_number));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.installments TO authenticated;GRANT ALL ON public.installments TO service_role;ALTER TABLE public.installments ENABLE ROW LEVEL SECURITY;CREATE POLICY installments_read ON public.installments FOR SELECT TO authenticated USING(buyer_id=auth.uid() OR public.is_admin());CREATE POLICY installments_create ON public.installments FOR INSERT TO authenticated WITH CHECK(buyer_id=auth.uid() OR public.is_admin());CREATE POLICY installments_update ON public.installments FOR UPDATE TO authenticated USING(buyer_id=auth.uid() OR public.is_admin()) WITH CHECK(buyer_id=auth.uid() OR public.is_admin());CREATE POLICY installments_admin_delete ON public.installments FOR DELETE TO authenticated USING(public.is_admin());
CREATE TABLE public.payment_gateways(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL UNIQUE,label text NOT NULL,is_enabled boolean DEFAULT false,config jsonb DEFAULT '{}',webhook_secret text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.payment_gateways TO authenticated;GRANT ALL ON public.payment_gateways TO service_role;ALTER TABLE public.payment_gateways ENABLE ROW LEVEL SECURITY;CREATE POLICY payment_gateways_admin ON public.payment_gateways FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());ALTER TABLE public.transactions ADD CONSTRAINT transactions_gateway_fk FOREIGN KEY(payment_gateway_id) REFERENCES public.payment_gateways(id);
CREATE TABLE public.documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,file_url text NOT NULL,file_type text,animal_id uuid REFERENCES public.animals(id) ON DELETE CASCADE,event_id uuid REFERENCES public.events(id) ON DELETE CASCADE,lot_id uuid REFERENCES public.lots(id) ON DELETE CASCADE,user_id uuid,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.documents TO authenticated;GRANT ALL ON public.documents TO service_role;ALTER TABLE public.documents ENABLE ROW LEVEL SECURITY;CREATE POLICY documents_own_or_admin ON public.documents FOR ALL TO authenticated USING(user_id=auth.uid() OR public.is_admin()) WITH CHECK(user_id=auth.uid() OR public.is_admin());
CREATE TABLE public.event_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid,name text NOT NULL,whatsapp text NOT NULL,email text,category text,location text,additional_info text,estimated_date text,estimated_animals text,status text DEFAULT 'pending',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT INSERT ON public.event_requests TO anon,authenticated;GRANT SELECT,UPDATE,DELETE ON public.event_requests TO authenticated;GRANT ALL ON public.event_requests TO service_role;ALTER TABLE public.event_requests ENABLE ROW LEVEL SECURITY;CREATE POLICY event_requests_create ON public.event_requests FOR INSERT TO anon,authenticated WITH CHECK(user_id IS NULL OR user_id=auth.uid());CREATE POLICY event_requests_read ON public.event_requests FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_admin());CREATE POLICY event_requests_admin ON public.event_requests FOR UPDATE TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());CREATE POLICY event_requests_delete ON public.event_requests FOR DELETE TO authenticated USING(public.is_admin());
CREATE TABLE public.direct_sales(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),animal_id uuid NOT NULL REFERENCES public.animals(id) ON DELETE CASCADE,buyer_id uuid,buyer_name text,buyer_email text,buyer_phone text,total_price numeric NOT NULL,status text DEFAULT 'pending',shipping_details jsonb,negotiated_terms text,accepted_at timestamptz,accepted_ip text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT INSERT ON public.direct_sales TO anon,authenticated;GRANT SELECT,UPDATE,DELETE ON public.direct_sales TO authenticated;GRANT ALL ON public.direct_sales TO service_role;ALTER TABLE public.direct_sales ENABLE ROW LEVEL SECURITY;CREATE POLICY direct_sales_create ON public.direct_sales FOR INSERT TO anon,authenticated WITH CHECK(buyer_id IS NULL OR buyer_id=auth.uid());CREATE POLICY direct_sales_read ON public.direct_sales FOR SELECT TO authenticated USING(buyer_id=auth.uid() OR public.is_admin());CREATE POLICY direct_sales_admin ON public.direct_sales FOR UPDATE TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());CREATE POLICY direct_sales_delete ON public.direct_sales FOR DELETE TO authenticated USING(public.is_admin());
CREATE TABLE public.offers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),lot_id uuid REFERENCES public.lots(id) ON DELETE CASCADE,animal_id uuid REFERENCES public.animals(id) ON DELETE CASCADE,user_id uuid NOT NULL,amount numeric,description text,status text DEFAULT 'pending',negotiated_terms text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.offers TO authenticated;GRANT ALL ON public.offers TO service_role;ALTER TABLE public.offers ENABLE ROW LEVEL SECURITY;CREATE POLICY offers_read ON public.offers FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_admin());CREATE POLICY offers_create ON public.offers FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());CREATE POLICY offers_admin_update ON public.offers FOR UPDATE TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());CREATE POLICY offers_delete ON public.offers FOR DELETE TO authenticated USING(user_id=auth.uid() OR public.is_admin());
CREATE TABLE public.followed_lots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,lot_id uuid NOT NULL REFERENCES public.lots(id) ON DELETE CASCADE,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,lot_id));
GRANT SELECT,INSERT,DELETE ON public.followed_lots TO authenticated;GRANT ALL ON public.followed_lots TO service_role;ALTER TABLE public.followed_lots ENABLE ROW LEVEL SECURITY;CREATE POLICY followed_read ON public.followed_lots FOR SELECT TO authenticated USING(user_id=auth.uid());CREATE POLICY followed_create ON public.followed_lots FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());CREATE POLICY followed_delete ON public.followed_lots FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),sender_id uuid NOT NULL,recipient_id uuid NOT NULL,title text,content text NOT NULL,is_read boolean DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.messages TO authenticated;GRANT ALL ON public.messages TO service_role;ALTER TABLE public.messages ENABLE ROW LEVEL SECURITY;CREATE POLICY messages_read ON public.messages FOR SELECT TO authenticated USING(sender_id=auth.uid() OR recipient_id=auth.uid() OR public.is_admin());CREATE POLICY messages_create ON public.messages FOR INSERT TO authenticated WITH CHECK(sender_id=auth.uid() OR public.is_admin());CREATE POLICY messages_update ON public.messages FOR UPDATE TO authenticated USING(recipient_id=auth.uid() OR public.is_admin()) WITH CHECK(recipient_id=auth.uid() OR public.is_admin());CREATE POLICY messages_delete ON public.messages FOR DELETE TO authenticated USING(sender_id=auth.uid() OR recipient_id=auth.uid() OR public.is_admin());
CREATE TABLE public.chat_threads(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,title text NOT NULL DEFAULT 'Nova conversa',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.chat_threads TO authenticated;GRANT ALL ON public.chat_threads TO service_role;ALTER TABLE public.chat_threads ENABLE ROW LEVEL SECURITY;CREATE POLICY threads_own ON public.chat_threads FOR ALL TO authenticated USING(user_id=auth.uid() OR public.is_admin()) WITH CHECK(user_id=auth.uid() OR public.is_admin());
CREATE TABLE public.chat_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),thread_id uuid NOT NULL REFERENCES public.chat_threads(id) ON DELETE CASCADE,user_id uuid NOT NULL,role text NOT NULL,parts jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.chat_messages TO authenticated;GRANT ALL ON public.chat_messages TO service_role;ALTER TABLE public.chat_messages ENABLE ROW LEVEL SECURITY;CREATE POLICY chat_messages_own ON public.chat_messages FOR ALL TO authenticated USING(user_id=auth.uid() OR public.is_admin()) WITH CHECK(user_id=auth.uid() OR public.is_admin());
CREATE OR REPLACE FUNCTION public.touch_chat_thread() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$BEGIN UPDATE public.chat_threads SET updated_at=now() WHERE id=NEW.thread_id;RETURN NEW;END$$;CREATE TRIGGER on_chat_message AFTER INSERT ON public.chat_messages FOR EACH ROW EXECUTE FUNCTION public.touch_chat_thread();REVOKE ALL ON FUNCTION public.touch_chat_thread() FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.touch_chat_thread() TO service_role;
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['transactions','contracts','installments','payment_gateways','event_requests','direct_sales','offers','messages','chat_threads'] LOOP EXECUTE format('CREATE TRIGGER touch_%I_updated_at BEFORE UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at()',t,t);END LOOP;END$$;
CREATE INDEX idx_transactions_buyer ON public.transactions(buyer_id);CREATE INDEX idx_installments_buyer ON public.installments(buyer_id,due_date);CREATE INDEX idx_offers_user ON public.offers(user_id);CREATE INDEX idx_followed_user ON public.followed_lots(user_id);CREATE INDEX idx_messages_recipient ON public.messages(recipient_id,is_read);CREATE INDEX idx_chat_threads_user ON public.chat_threads(user_id,updated_at DESC);CREATE INDEX idx_chat_messages_thread ON public.chat_messages(thread_id,created_at);
INSERT INTO public.payment_gateways(name,label,is_enabled,config) VALUES('pix_manual','PIX Manual',true,'{}'),('mercado_pago','Mercado Pago',false,'{}'),('pagbank','PagBank',false,'{}');